candidates.issueBody:
In my app, i want render all the suggestions each time user focuses and if user has selected any value previously that should remain. For eg: If user has selected C# and blurs out. Now again user focuses back on input field , the suggested value 'C#' should remain and all the suggestions should be rendered. Is there way to do this ? I tried setting suggestions onFocus didn't work. I'm attaching my component where i have used 
```js
import React, { Component } from 'react';
import { connect } from 'react-redux';
import Autosuggest from 'react-autosuggest';
import { fromJS } from 'immutable';
import { actions } from '../../redux/modules/Rulebook';

/**
@projectList is list of projectList to filter
@value is value to filter
@returns suggestions for auto suggest
*/
function getSuggestions(value, projectList) {
    const inputValue = value.trim().toLowerCase();
    const inputLength = inputValue.length;
    let suggestions = projectList;
    if (inputLength > 0) {
        suggestions = projectList.filter(content =>
            content.toLowerCase().includes(inputValue)
        );
    }
    return suggestions;
}

const getSuggestionValue = suggestion => suggestion;

const renderSuggestion = suggestion => (
    <div> {suggestion} </div>
);

/**
 * RulebookModal
 * Description of what this component does
 * goes here.
 */
export class RulebookModalComponent extends Component {
    constructor(props) {
        super(props);
        const projectList = props.projectList.map(item => item.get('name')).toJS();
        let value = '';
        if (props.questionBuilder.get('projectId')) {
            value = props.projectList.find(item =>
                item.get('id') === props.questionBuilder.get('projectId')
            ).get('name');
        }
        const buttonText = props.type === 'create' ? `CREATE ${props.builderType}` :
            `CREATE DUPLICATED ${props.builderType}`;
        this.state = {
            value,
            suggestions: getSuggestions('', projectList),
            projectList,
            buttonText,
            showSuggestions: false,
            toClone: props.type === 'duplicate',
            hasCloneModal: props.hasCloneModal
        };
        this.getOptions = this.getOptions.bind(this);
        this.selectProjectType = this.selectProjectType.bind(this);
        this.selectContentOwner = this.selectContentOwner.bind(this);
        this.selectPlatform = this.selectPlatform.bind(this);
        this.getTemplateInfo = this.getTemplateInfo.bind(this);
        this.getRuleBookInfo = this.getRuleBookInfo.bind(this);
        this.filterProjectTypeList = this.filterProjectTypeList.bind(this);
        this.createQuestionBuilder = this.createQuestionBuilder.bind(this);
        this.uniquePlatformList = this.uniquePlatformList.bind(this);
        this.getNameById = this.getNameById.bind(this);
        this.isValidBuilder = this.isValidBuilder.bind(this);
        this.onChange = this.onChange.bind(this);
        this.onSuggestionsFetchRequested = this.onSuggestionsFetchRequested.bind(this);
        this.onSuggestionsClearRequested = this.onSuggestionsClearRequested.bind(this);
        this.onSuggestionSelected = this.onSuggestionSelected.bind(this);
        this.onFocus = this.onFocus.bind(this);
        this.onBlur = this.onBlur.bind(this);
        this.setCloneState = this.setCloneState.bind(this);
        this.getModalBody = this.getModalBody.bind(this);
        this.setDisplayTitle = this.setDisplayTitle.bind(this);
    }

    componentWillReceiveProps(nextProps) {
        if (nextProps.apiError && (nextProps.apiError !== this.props.apiError)) {
            const buttonText = this.props.type === 'create' ? `CREATE ${this.props.builderType}` :
            `CREATE DUPLICATED ${this.props.builderType}`;
            this.setState({ buttonText });
        }
    }

    onChange(event, { newValue }) {
        this.setState({
            value: newValue
        });
    }

    onFocus() {
        this.setState({ showSuggestions: true });
    }

    onBlur() {
        this.setState({ showSuggestions: false });
        if (!this.state.value) {
            this.props.selectContentOwner({ projectId: '' });
        }
    }

    onSuggestionsFetchRequested({ value }) {
        this.setState({
            suggestions: getSuggestions(value, this.state.projectList)
        });
    }

    onSuggestionsClearRequested() {
        this.setState({
            suggestions: getSuggestions('', this.state.projectList)
        });
    }

    onSuggestionSelected(event, { suggestionValue }) {
        this.setState({ showSuggestions: false });
        const selectedProject = this.props.projectList.find(item =>
            item.get('name') === suggestionValue
        );
        this.props.selectContentOwner({ projectId: parseInt(selectedProject.get('id'), 10) });
    }

    getNameById(list, id, fieldName) {
        const currItem = list.find(arr => arr.get('id') === id);
        if (fieldName === 'projectType' && this.props.builderType === 'rulebook') {
            return (currItem ? `${currItem.get(fieldName)} - ${currItem.get('platform')}` : '');
        }
        return (currItem ? currItem.get(fieldName) : '');
    }

    getOptions(list, type, hasValueSelected) {
        const placeHolders = { projectType: 'Choose a template',
            partner: 'Select partner',
            contentOwner: 'Choose a content owner',
            title: 'Title Name (optional)',
            platform: 'Select Platform',
            displayTitle: 'Choose a template'
        };
        let options = [];
        if (list) {
            const subArray = Array.from(new Set(list.map(item => item.get('id'))));
            options = subArray.map((item) => {
                const fieldLabel = type === 'contentOwner' ? 'name' : type;

                const option = (<option key={item} value={item}>
                    {this.getNameById(list, item, fieldLabel)}
                </option>);
                return option;
            });
        }
        if (type) {
            options.unshift(<option key={0} value="" disabled={hasValueSelected}>
                {placeHolders[type]}</option>);
        }
        return options;
    }

    getProjectTypeTag() {
        let returnObj = (<select
            id="create-rulebook-project-type-dropdown"
            className="h40"
            onChange={(e) => this.selectProjectType(e)}
            value={this.props.questionBuilder.get('projectTypeId')}
        >
            {this.getOptions(this.props.projectTypeList, 'projectType',
            this.props.questionBuilder.get('projectTypeId'))}
        </select>);
        if (this.state.hasCloneModal !== undefined && this.state.toClone) {
            const publishedList = this.props.templateList.map(template =>
                fromJS({ id: template.get('id'),
                    displayTitle: template.getIn(['versions', 0, 'displayTitle'])
                })
            );
            returnObj = (<select
                className="h40 test-select-template-component"
                onChange={(e) => this.selectTemplate(e)}
                value={this.props.questionBuilder.get('builderId')}
            >
                {this.getOptions(publishedList, 'displayTitle',
                this.props.questionBuilder.get('builderId'))}
            </select>);
        }
        return returnObj;
    }

    getTemplateInfo() {
        return (<div className="w450">
            <div className="custom-select mb10 required">
                <div className="tiny-label">Choose Platform</div>
                <select
                    id="create-template-platform-dropdown"
                    onChange={(e) => this.selectPlatform(e)}
                    className="h40"
                >
                    {this.getOptions(this.uniquePlatformList(), 'platform',
                        this.props.questionBuilder.get('platform'))}
                </select>
            </div>
            <div className="custom-select mb10 required">
                <div className="tiny-label">Select Project </div>
                <select
                    id="create-template-project-type-dropdown"
                    onChange={(e) => this.selectProjectType(e)}
                    className="h40"
                >
                    {this.getOptions(this.filterProjectTypeList(), 'projectType',
                        this.props.questionBuilder.get('projectTypeId'))}
                </select>
            </div>
        </div>);
    }

    setCloneState(value) {
        const buttonText = value ? 'CREATE DUPLICATED RULEBOOK' : 'CREATE RULEBOOK';
        this.setState({ toClone: value });
        this.setState({ hasCloneModal: false });
        this.setState({ buttonText });
    }

    getRuleBookInfo() {
        const disableCOClass = this.props.questionBuilder.get('projectTypeId') ?
            '' : 'disabled';
        return (<div className="row text-left">
            <div className="col-95 custom-select mb10 required">
                <div className="tiny-label">Choose a template</div>
                {this.getProjectTypeTag()}
            </div>
            <div className={`col-95 custom-select mb10 required react-dd ${disableCOClass}`}>
                <div className="tiny-label">Select content owner</div>
                {this.renderAutoSuggest()}
            </div>
            <div className="col-95 mb10">
                <div className="tiny-label">RuleBook Name</div>
                <input
                    className="h40"
                    value={this.props.questionBuilder.get('displayTitle')}
                    type="text"
                    onChange={this.setDisplayTitle}
                />
            </div>
            <div className="col-5" >
                <a className="inblock lh0 mb10 ml10 alignmiddle show-tip ontop cursor">
                    <svg className="icon-w20 theme-fill">
                        <use
                            xlinkHref="../../images/sprite.svg#info"
                            xmlnsXlink="http://www.w3.org/1999/xlink"
                        />
                    </svg>
                    <div className="tooltip on-right f12 p10 lh-n animate width225">
                        Entering a title name & ID makes this rulebook applicable only to that
                        title.
                    </div>
                </a>
            </div>
        </div>);
    }

    getModalBody() {
        let builderDiv = null;
        if (this.props.builderType) {
            builderDiv = (this.props.builderType.indexOf('rulebook') > -1 ?
            this.getRuleBookInfo() : this.getTemplateInfo());
        }

        const headerText = !this.state.toClone ? 'Add new' : 'Duplicate';
        let returnObj = (<div>
            <div
                id={`create-${this.props.builderType}-modal-header`}
                className="fw-l f24 text-capitalize"
            >
                {headerText} {(this.props.builderType)}
            </div>
            <div className="f12 lh-n fw-l text-left mb5">
                <b className="req-dot mr5" />
                Required fields
            </div>
            {builderDiv}
            <div className="pt20 mb10">
                <button
                    id={`create-${this.props.builderType}-button`}
                    className="btn fw-sb f12 p10 zefr-primary cursor
                            test-create-question-builder"
                    onClick={this.createQuestionBuilder}
                    disabled={this.isValidBuilder()}
                >
                    {this.state.buttonText}
                </button>
            </div>
        </div>);
        if (this.state.hasCloneModal) {
            returnObj = (<div className="test-clonemodal-component">
                CREATE RULEBOOK
                <div className="pt20 mb10">
                    <button
                        className="btn fw-sb f12 p10 zefr-primary cursor
                            test-clone-rulebook-button pl30 pr30"
                        onClick={() => this.setCloneState(true)}
                    >
                        CLONE FROM EXISTING TEMPLATE
                    </button>
                </div>
                <div className="pt20 mb10">
                    <button
                        className="btn fw-sb f12 p10 zefr-primary cursor
                            test-create-rulebook-builder"
                        onClick={() => this.setCloneState(false)}
                    >
                        CREATE NEW RULEBOOK FROM SCRATCH
                    </button>
                </div>
            </div>);
        }
        return returnObj;
    }

    setDisplayTitle(e) {
        this.props.setDisplayTitle({ displayTitle: e.target.value });
    }

    uniquePlatformList() {
        if (this.props.projectTypeList && this.props.projectTypeList.size) {
            const temp = this.props.projectTypeList.map(el => el.get('platform'));
            return this.props.projectTypeList.filter((el, i) =>
                temp.indexOf(el.get('platform')) === i
            );
        }
        return null;
    }

    // filters projecttype list based on selected platform
    filterProjectTypeList() {
        let list;
        if (this.props.questionBuilder && this.props.questionBuilder.get('platform')) {
            list = this.props.projectTypeList.filter(item =>
                item.get('platform') === this.props.questionBuilder.get('platform')
            );
        }
        return list;
    }

    selectProjectType(e) {
        this.props.selectProjectType({ projectTypeId: e.target.value });
        this.setState({ value: '' });
    }

    selectContentOwner(e) {
        this.props.selectContentOwner({ projectId: e.target.value });
    }

    selectPlatform(e) {
        const project = this.props.projectTypeList.find(item =>
            item.get('id') === parseInt(e.target.value, 10)
        );
        this.props.selectPlatform(project.get('platform'));
    }

    selectTemplate(e) {
        const selectedBuilder = this.props.templateList.find(template =>
            template.get('id') === parseInt(e.target.value, 10)
        );
        this.setState({ value: '' });
        if (selectedBuilder) {
            const builder = { builderId: selectedBuilder.get('id'),
                builderType: 'rulebook',
                projectTypeId: selectedBuilder.get('projectTypeId')
            };
            this.props.initialiseQuestionBuilder(builder);
        }
    }

    createQuestionBuilder() {
        const buttonText = this.props.type === 'create' ? 'CREATING' : 'DUPLICATING';
        this.setState({ buttonText });
        if (!this.state.toClone) {
            this.props.createQuestionBuilder(this.props.questionBuilder);
        } else {
            if (this.props.questionData && !this.props.questionData.size) {
                this.props.fetchQuestionData();
            }
            this.props.duplicateBuilder(this.props.questionBuilder);
        }
    }

    isValidBuilder() {
        let validBuilder = false;
        if (this.props.questionBuilder.get('builderType') === 'rulebook') {
            validBuilder = isNaN(this.props.questionBuilder.get('projectTypeId')) ||
                isNaN(this.props.questionBuilder.get('projectId')) ||
                !this.props.questionBuilder.get('projectId') ||
                !this.props.questionBuilder.get('displayTitle');
        } else {
            validBuilder = isNaN(this.props.questionBuilder.get('projectTypeId'));
        }
        return validBuilder;
    }

    renderAutoSuggest() {
        let returnObj = null;
        const { value, suggestions } = this.state;
        const inputProps = {
            placeholder: 'Select content owner',
            value,
            onChange: this.onChange,
            onBlur: this.onBlur,
            onFocus: this.onFocus,
            id: 'create-rulebook-content-owner-dropdown',
            className: 'content-owner'
        };
        returnObj = (<Autosuggest
            suggestions={suggestions}
            onSuggestionsFetchRequested={this.onSuggestionsFetchRequested}
            onSuggestionsClearRequested={this.onSuggestionsClearRequested}
            getSuggestionValue={getSuggestionValue}
            renderSuggestion={renderSuggestion}
            inputProps={inputProps}
            onSuggestionSelected={this.onSuggestionSelected}
            onBlur={(e) => this.updateGroupName(e)}
            alwaysRenderSuggestions={this.state.showSuggestions}
        />);
        return returnObj;
    }

    render() {
        const hideClass = this.props.showModal ? '' : 'hide';
        let projectTypeSelectedClass = null;
        if (this.props.questionBuilder && this.props.questionBuilder.get('projectTypeId')) {
            const selectedProject = this.props.projectTypeList.find(item =>
                parseInt(this.props.questionBuilder.get('projectTypeId'), 10) ===
                item.get('id')
            );
            projectTypeSelectedClass = selectedProject ? selectedProject.get('projectType') : '';
        }
        const errorMessage = this.props.apiError && this.props.apiError.size ?
        (<div className="error-banner fw-r">
            {this.props.apiError.getIn([0, 'error'])}
        </div>) : '';
        return (
            <div className="create-rulebook-modal test-rulebook-modal-component">
                {errorMessage}
                <div id={`create-${this.props.builderType}-modal`} className={`popup ${hideClass}`}>
                    <div
                        className={'centermiddle text-center w500 fw-l ' +
							`whitebox p20 pl30 pr30 ${projectTypeSelectedClass}`}
                    >
                        <a
                            className="topright mr15 mt15 cursor"
                            onClick={() => this.props.setModal(false)}
                            id={`create-${this.props.builderType}-button`}
                        >
                            <svg className="icon-w20">
                                <use
                                    xlinkHref="../../images/sprite.svg#close"
                                    xmlnsXlink="http://www.w3.org/1999/xlink"
                                />
                            </svg>
                        </a>
                        {this.getModalBody()}
                    </div>
                </div>
            </div>
        );
    }
}

const mapStateToProps = (state) => {
    const projectList = state.Rulebook.get('projectList').sort((a, b) =>
        a.get('name').localeCompare(b.get('name'))
    );
    return {
        projectList,
        projectTypeList: state.Rulebook.get('projectTypeList'),
        titleList: state.Rulebook.get('titleList'),
        questionBuilder: state.Rulebook.get('questionBuilder'),
        apiError: state.Rulebook.get('apiError'),
        templateList: state.Rulebook.get('templateList').get('questionBuilders'),
        questionData: state.DecisionTree.get('questionData')
    };
};

/**
 * [propTypes description]
 */
RulebookModalComponent.propTypes = {
    projectList: React.PropTypes.object,
    projectTypeList: React.PropTypes.object,
    questionBuilder: React.PropTypes.object,
    apiError: React.PropTypes.object,
    selectPlatform: React.PropTypes.func,
    selectProjectType: React.PropTypes.func,
    selectContentOwner: React.PropTypes.func,
    setDisplayTitle: React.PropTypes.func,
    createQuestionBuilder: React.PropTypes.func,
    builderType: React.PropTypes.string,
